# Add firmware workarounds required by current Snapdragon laptops.

DROP_IN="/etc/limine-entry-tool.d/qualcomm-snapdragon.conf"

if omarchy-hw-aarch64-qualcomm; then
  mkdir -p /etc/limine-entry-tool.d
  cat >"$DROP_IN" <<'CONF'
# Generated by Omarchy for Qualcomm Snapdragon devices.
# Keep display and I/O resources enabled until their drivers load.
# Disable pointer authentication and waiting for an unavailable TPM.
KERNEL_CMDLINE[default]+=" clk_ignore_unused pd_ignore_unused regulator_ignore_unused arm64.nopauth systemd.tpm2_wait=0"
# Translate device memory access, as Arch Linux ARM's kernel does by default.
# On a kernel that defaults to passthrough, the Yoga Slim 7x's keyboard,
# touchpad and touchscreen read back empty descriptors and never appear.
KERNEL_CMDLINE[default]+=" iommu.passthrough=0"
CONF

  # Draw the splash and disk unlock prompt on the firmware framebuffer. The Yoga Slim 7x
  # blacklists simpledrm (lenovo/yoga-slim7x.sh) and unlocks through msm, so it keeps its own setup.
  if ! omarchy-hw-match "83ED"; then
    cat >>"$DROP_IN" <<'CONF'
KERNEL_CMDLINE[default]+=" splash plymouth.use-simpledrm"
CONF
  fi
fi
